57	func (st ServerType) Setup(
58		inputServerBlocks []caddyfile.ServerBlock,
59		options map[string]any,
60	) (*caddy.Config, []caddyconfig.Warning, error) {
61		var warnings []caddyconfig.Warning
62		gc := counter{new(int)}
63		state := make(map[string]any)
64	
65		// load all the server blocks and associate them with a "pile" of config values
66		originalServerBlocks := make([]serverBlock, 0, len(inputServerBlocks))
67		for _, sblock := range inputServerBlocks {
68			for j, k := range sblock.Keys {
69				if j == 0 && strings.HasPrefix(k.Text, "@") {
70					return nil, warnings, fmt.Errorf("%s:%d: cannot define a matcher outside of a site block: '%s'", k.File, k.Line, k.Text)
71				}
72				if _, ok := registeredDirectives[k.Text]; ok {
73					return nil, warnings, fmt.Errorf("%s:%d: parsed '%s' as a site address, but it is a known directive; directives must appear in a site block", k.File, k.Line, k.Text)
74				}
75			}
76			originalServerBlocks = append(originalServerBlocks, serverBlock{
77				block: sblock,
78				pile:  make(map[string][]ConfigValue),
79			})
80		}
81	
82		// apply any global options
83		var err error
84		originalServerBlocks, err = st.evaluateGlobalOptionsBlock(originalServerBlocks, options)
85		if err != nil {
86			return nil, warnings, err
87		}
88	
89		// this will replace both static and user-defined placeholder shorthands
90		// with actual identifiers used by Caddy
91		replacer := NewShorthandReplacer()
92	
93		originalServerBlocks, err = st.extractNamedRoutes(originalServerBlocks, options, &warnings, replacer)
94		if err != nil {
95			return nil, warnings, err
96		}
97	
98		for _, sb := range originalServerBlocks {
99			for i := range sb.block.Segments {
100				replacer.ApplyToSegment(&sb.block.Segments[i])
101			}
102	
103			if len(sb.block.Keys) == 0 {
104				return nil, warnings, fmt.Errorf("server block without any key is global configuration, and if used, it must be first")
105			}
106	
107			// extract matcher definitions
108			matcherDefs := make(map[string]caddy.ModuleMap)
109			for _, segment := range sb.block.Segments {
110				if dir := segment.Directive(); strings.HasPrefix(dir, matcherPrefix) {
111					d := caddyfile.NewDispenser(segment)
112					err := parseMatcherDefinitions(d, matcherDefs)
113					if err != nil {
114						return nil, warnings, err
115					}
116				}
117			}
118	
119			// evaluate each directive ("segment") in this block
120			for _, segment := range sb.block.Segments {
121				dir := segment.Directive()
122	
123				if strings.HasPrefix(dir, matcherPrefix) {
124					// matcher definitions were pre-processed
125					continue
126				}
127	
128				dirFunc, ok := registeredDirectives[dir]
129				if !ok {
130					tkn := segment[0]
131					message := "%s:%d: unrecognized directive: %s"
132					if !sb.block.HasBraces {
133						message += "\nDid you mean to define a second site? If so, you must use curly braces around each site to separate their configurations."
134					}
135					return nil, warnings, fmt.Errorf(message, tkn.File, tkn.Line, dir)
136				}
137	
138				h := Helper{
139					Dispenser:    caddyfile.NewDispenser(segment),
140					options:      options,
141					warnings:     &warnings,
142					matcherDefs:  matcherDefs,
143					parentBlock:  sb.block,
144					groupCounter: gc,
145					State:        state,
146					BlockState:   state,
147				}
148	
149				results, err := dirFunc(h)
150				if err != nil {
151					return nil, warnings, fmt.Errorf("parsing caddyfile tokens for '%s': %v", dir, err)
152				}
153	
154				dir = normalizeDirectiveName(dir)
155	
156				for _, result := range results {
157					result.directive = dir
158					sb.pile[result.Class] = append(sb.pile[result.Class], result)
159				}
160	
161				// specially handle named routes that were pulled out from
162				// the invoke directive, which could be nested anywhere within
163				// some subroutes in this directive; we add them to the pile
164				// for this server block
165				if state[namedRouteKey] != nil {
166					for name := range state[namedRouteKey].(map[string]struct{}) {
167						result := ConfigValue{Class: namedRouteKey, Value: name}
168						sb.pile[result.Class] = append(sb.pile[result.Class], result)
169					}
170					state[namedRouteKey] = nil
171				}
172			}
173		}
174	
175		// map
176		sbmap, err := st.mapAddressToProtocolToServerBlocks(originalServerBlocks, options)
177		if err != nil {
178			return nil, warnings, err
179		}
180	
181		// reduce
182		pairings := st.consolidateAddrMappings(sbmap)
183	
184		// each pairing of listener addresses to list of server
185		// blocks is basically a server definition
186		servers, err := st.serversFromPairings(pairings, options, &warnings, gc)
187		if err != nil {
188			return nil, warnings, err
189		}
190	
191		// hoist the metrics config from per-server to global
192		metrics, _ := options["metrics"].(*caddyhttp.Metrics)
193		for _, s := range servers {
194			if s.Metrics != nil {
195				metrics = cmp.Or(metrics, &caddyhttp.Metrics{})
196				metrics = &caddyhttp.Metrics{
197					PerHost: metrics.PerHost || s.Metrics.PerHost,
198				}
199				s.Metrics = nil // we don't need it anymore
200			}
201		}
202	
203		// now that each server is configured, make the HTTP app
204		httpApp := caddyhttp.App{
205			HTTPPort:      tryInt(options["http_port"], &warnings),
206			HTTPSPort:     tryInt(options["https_port"], &warnings),
207			GracePeriod:   tryDuration(options["grace_period"], &warnings),
208			ShutdownDelay: tryDuration(options["shutdown_delay"], &warnings),
209			Metrics:       metrics,
210			Servers:       servers,
211		}
212	
213		// then make the TLS app
214		tlsApp, warnings, err := st.buildTLSApp(pairings, options, warnings)
215		if err != nil {
216			return nil, warnings, err
217		}
218	
219		// then make the PKI app
220		pkiApp, warnings, err := st.buildPKIApp(pairings, options, warnings)
221		if err != nil {
222			return nil, warnings, err
223		}
224	
225		// extract any custom logs, and enforce configured levels
226		var customLogs []namedCustomLog
227		var hasDefaultLog bool
228		addCustomLog := func(ncl namedCustomLog) {
229			if ncl.name == "" {
230				return
231			}
232			if ncl.name == caddy.DefaultLoggerName {
233				hasDefaultLog = true
234			}
235			if _, ok := options["debug"]; ok && ncl.log != nil && ncl.log.Level == "" {
236				ncl.log.Level = zap.DebugLevel.CapitalString()
237			}
238			customLogs = append(customLogs, ncl)
