297	func TestImportDiamondSameFileNotCycle(t *testing.T) {
298		dir := t.TempDir()
299		writeImportFile(t, filepath.Join(dir, "d.conf"), site("host-d"))
300		writeImportFile(t, filepath.Join(dir, "b.conf"), "import d.conf\n")
301		writeImportFile(t, filepath.Join(dir, "c.conf"), "import d.conf\n")
302		writeImportFile(t, filepath.Join(dir, "a.conf"), "import b.conf\nimport c.conf\n")
303	
304		blocks, err := parseInDir(t, dir, "import "+filepath.Join(dir, "a.conf")+"\n")
305		if err != nil {
306			t.Fatalf("expected a shared leaf not to be a cycle, got: %v", err)
307		}
308	
309		got := blockKeys(blocks)
310		if len(got) != 2 || got[0] != "host-d" || got[1] != "host-d" {
311			t.Errorf("expected two host-d expansions, got %v", got)
312		}
313	}
314	
315	// Directories remain an error using the existing category.
316	func TestImportDirectoryStillErrors(t *testing.T) {
317		dir := t.TempDir()
318		sub := filepath.Join(dir, "subdir")
319		if err := os.Mkdir(sub, 0o755); err != nil {
320			t.Fatal(err)
321		}
322		_, err := parseInDir(t, dir, "import "+sub+"\n")
323		if err == nil {
324			t.Fatal("expected an error importing a directory, got nil")
325		}
326		if !strings.Contains(err.Error(), "is a directory") {
327			t.Errorf("expected a directory error category, got: %v", err)
328		}
329	}
330	
331	// A glob matching nothing is still a non-error; an explicit missing file
332	// is still an error.
333	func TestImportNoMatchCategories(t *testing.T) {
334		dir := t.TempDir()
335		if _, err := parseInDir(t, dir, "import "+filepath.Join(dir, "nope", "*.conf")+"\n"); err != nil {
336			t.Errorf("expected a non-matching glob to be a non-error, got: %v", err)
337		}
338		if _, err := parseInDir(t, dir, "import "+filepath.Join(dir, "nope", "file.conf")+"\n"); err == nil {
339			t.Error("expected a missing explicit file to be an error, got nil")
340		}
341	}
342	
343	// Repeatedly adapting the same file tree yields identical expansion
344	// order; a cycle yields the identical error chain.
345	func TestImportDeterministicAcrossRuns(t *testing.T) {
346		dir := t.TempDir()
347		writeImportFile(t, filepath.Join(dir, "a.conf"), site("host-a"))
348		writeImportFile(t, filepath.Join(dir, "m.conf"), site("host-m"))
349		symlinkOrSkip(t, filepath.Join(dir, "a.conf"), filepath.Join(dir, "z-alias.conf"))
350		root := filepath.Join(dir, "Caddyfile")
351		body := []byte("import " + filepath.Join(dir, "*") + "\n")
352	
353		var first []string
354		for run := 0; run < 3; run++ {
355			blocks, err := Parse(root, body)
356			if err != nil {
357				t.Fatalf("run %d: expected no error, got: %v", run, err)
358			}
359			keys := blockKeys(blocks)
360			if first == nil {
361				first = keys
362				continue
363			}
364			if strings.Join(keys, ",") != strings.Join(first, ",") {
365				t.Errorf("run %d: expected %v, got %v", run, first, keys)
366			}
367		}
368	
369		// error chain stability
370		cyc := filepath.Join(dir, "cyc.conf")
371		writeImportFile(t, cyc, "import link2.conf\n")
372		symlinkOrSkip(t, cyc, filepath.Join(dir, "link2.conf"))
373		cycleBody := []byte("import " + cyc + "\n")
374		var firstErr string
375		for run := 0; run < 3; run++ {
376			_, err := Parse(root, cycleBody)
377			if err == nil {
378				t.Fatalf("run %d: expected a cycle error, got nil", run)
379			}
380			if firstErr == "" {
381				firstErr = err.Error()
382				continue
383			}
384			if err.Error() != firstErr {
385				t.Errorf("run %d: expected identical error\nwant: %s\ngot:  %s", run, firstErr, err.Error())
386			}
387		}
388	}
389	
390	// Exercise the public Adapter.Adapt entry point: a glob that hits the
391	// same real file through an alias expands it once and succeeds, while a
392	// cycle means the whole adaptation fails (the caller never receives a
393	// partially expanded successful result).
394	func TestAdapterImportResolution(t *testing.T) {
395		dir := t.TempDir()
396		root := filepath.Join(dir, "Caddyfile")
397		writeImportFile(t, filepath.Join(dir, "a.conf"), site("host-a"))
398		writeImportFile(t, filepath.Join(dir, "m.conf"), site("host-m"))
399		symlinkOrSkip(t, filepath.Join(dir, "a.conf"), filepath.Join(dir, "z-alias.conf"))
400	
401		var captured []ServerBlock
402		adapter := Adapter{ServerType: captureServerType{blocks: &captured}}
403	
404		// success: alias + real file collapsed, order follows real paths
405		out, _, err := adapter.Adapt([]byte("import "+filepath.Join(dir, "*")+"\n"),
406			map[string]any{"filename": root})
407		if err != nil {
408			t.Fatalf("expected successful adaptation, got: %v", err)
409		}
410		if len(out) == 0 {
411			t.Error("expected non-empty JSON output, got empty")
412		}
413		if got := blockKeys(captured); strings.Join(got, ",") != "host-a,host-m" {
414			t.Errorf("expected hosts [host-a host-m], got %v", got)
415		}
416	
417		// failure: any imported file triggering a cycle fails the whole adapt
418		cyc := filepath.Join(dir, "cyc.conf")
419		writeImportFile(t, cyc, "import alias2.conf\n")
420		symlinkOrSkip(t, cyc, filepath.Join(dir, "alias2.conf"))
421		captured = nil
422		out, _, err = adapter.Adapt([]byte("import "+cyc+"\n"),
423			map[string]any{"filename": root})
424		if err == nil {
425			t.Fatal("expected the whole adaptation to fail on a cycle, got nil")
426		}
427		if out != nil {
428			t.Errorf("expected no partial result on failure (got %d bytes)", len(out))
429		}
430		if captured != nil {
431			t.Errorf("expected Setup not to run on a failed expansion (partial result)")
432		}
433		if !strings.Contains(err.Error(), "cycle") {
434			t.Errorf("expected a cycle diagnostic, got: %v", err)
435		}
436	}
437	
438	// A dangling symlink keeps the existing "not found / could not import"
439	// error category rather than surfacing a path-resolution error.
440	func TestAdapterDanglingSymlinkCategory(t *testing.T) {
441		dir := t.TempDir()
442		root := filepath.Join(dir, "Caddyfile")
443		symlinkOrSkip(t, filepath.Join("does-not-exist"), filepath.Join(dir, "dangling.conf"))
444	
445		var captured []ServerBlock
446		adapter := Adapter{ServerType: captureServerType{blocks: &captured}}
447		_, _, err := adapter.Adapt([]byte("import "+filepath.Join(dir, "dangling.conf")+"\n"),
448			map[string]any{"filename": root})
449		if err == nil {
450			t.Fatal("expected an error for a dangling symlink, got nil")
451		}
452		if strings.Contains(err.Error(), "Could not resolve import") {
453			t.Errorf("dangling symlink should keep existing I/O error category, got: %v", err)
454		}
455	}
456	
457	// A relative import in the entry file itself must resolve against the
458	// entry's real directory when the entry is named through a symlink; it
459	// must not drift to the directory the alias lives in.
460	func TestImportEntryRelativeThroughSymlink(t *testing.T) {
461		dir := t.TempDir()
462		writeImportFile(t, filepath.Join(dir, "real", "Caddyfile"), "import sub/b.conf\n"+site("host-a"))
463		writeImportFile(t, filepath.Join(dir, "real", "sub", "b.conf"), site("host-b"))
464		entry := filepath.Join(dir, "alias", "Caddyfile")
465		symlinkOrSkip(t, filepath.Join(dir, "real", "Caddyfile"), entry)
466	
467		body, err := os.ReadFile(entry)
468		if err != nil {
469			t.Fatal(err)
470		}
471		blocks, err := Parse(entry, body)
472		if err != nil {
473			t.Fatalf("expected relative import to resolve against the real entry, got: %v", err)
474		}
475	
476		got := blockKeys(blocks)
477		want := []string{"host-b", "host-a"}
478		if strings.Join(got, ",") != strings.Join(want, ",") {
479			t.Errorf("expected %v, got %v", want, got)
480		}
481	}
482	
483	// An entry reached through a symlink that imports itself via an alias in
484	// its own directory is a genuine cycle and must fail.
485	func TestImportEntryCycleThroughAlias(t *testing.T) {
486		dir := t.TempDir()
487		a := filepath.Join(dir, "real", "a.conf")
488		writeImportFile(t, a, "import link.conf\n"+site("host-a"))
489		symlinkOrSkip(t, a, filepath.Join(dir, "real", "link.conf"))
490		entry := filepath.Join(dir, "alias", "Caddyfile")
491		symlinkOrSkip(t, a, entry)
492	
493		_, err := Parse(entry, []byte("import link.conf\n"+site("host-root")))
494		if err == nil {
495			t.Fatal("expected a cycle error, got nil")
496		}
497		msg := err.Error()
498		if !strings.Contains(msg, "cycle") || !strings.Contains(msg, "a.conf") || !strings.Contains(msg, "link.conf") {
499			t.Errorf("expected a cycle chain naming the files, got: %v", err)
500		}
501	}
502	
503	// fsCaseInsensitive reports whether dir folds file-name case, observed from
504	// the live filesystem rather than from the target operating system. A
505	// default APFS or NTFS/FAT volume folds case even when the kernel is Unix-like.
506	func fsCaseInsensitive(t *testing.T, dir string) bool {
507		t.Helper()
508		probeName := ".case_probe_abc"
509		probe := filepath.Join(dir, probeName)
510		writeImportFile(t, probe, "")
511		info, err := os.Stat(probe)
512		if err != nil {
513			t.Skipf("cannot probe filesystem case rules: %v", err)
514		}
515		flipped, err := os.Stat(filepath.Join(dir, strings.ToUpper(probeName)))
516		if err != nil {
517			return false
518		}
519		return os.SameFile(info, flipped)
520	}
521	
522	// On a case-insensitive volume, aliases differing only in case (here a symlink
523	// whose target is spelled with different case) still denote the same real
524	// file: a single glob must expand it once and must not depend on a fixed
525	// per-OS folding rule.
526	func TestImportGlobDeduplicatesCaseOnlyAlias(t *testing.T) {
527		dir := t.TempDir()
528		if !fsCaseInsensitive(t, dir) {
529			t.Skip("requires a case-insensitive filesystem")
530		}
531		writeImportFile(t, filepath.Join(dir, "real", "a.conf"), site("host-a"))
532		writeImportFile(t, filepath.Join(dir, "m.conf"), site("host-m"))
533		// the target is spelled in a case that does not exist on disk
534		symlinkOrSkip(t, filepath.Join(dir, "REAL", "A.CONF"), filepath.Join(dir, "z-link.conf"))
535	
536		blocks, err := parseInDir(t, dir, "import "+filepath.Join(dir, "*.conf")+"\n")
537		if err != nil {
538			t.Fatalf("expected no error, got: %v", err)
539		}
540		got := blockKeys(blocks)
541		// the alias canonicalizes to real/a.conf, which sorts after m.conf;
542		// the important assertion is that the alias adds no extra expansion
543		want := []string{"host-m", "host-a"}
544		if strings.Join(got, ",") != strings.Join(want, ",") {
545			t.Errorf("expected %v (case alias collapsed, canonical order), got %v", want, got)
546		}
547	}
548	
549	// A cycle closed through a case-only alias on a case-insensitive volume must
550	// be detected and report the same chain on immediate retries.
551	func TestImportCycleThroughCaseOnlyAlias(t *testing.T) {
552		dir := t.TempDir()
553		if !fsCaseInsensitive(t, dir) {
554			t.Skip("requires a case-insensitive filesystem")
555		}
556		a := filepath.Join(dir, "a.conf")
557		writeImportFile(t, a, "import link.conf\n"+site("host-a"))
558		// the alias points at the same file using a different-case spelling
559		symlinkOrSkip(t, filepath.Join(dir, "A.CONF"), filepath.Join(dir, "link.conf"))
560	
561		body := []byte("import " + a + "\n")
562		var firstErr string
563		for run := 0; run < 2; run++ {
564			_, err := Parse(filepath.Join(dir, "Caddyfile"), body)
565			if err == nil {
566				t.Fatalf("run %d: expected a cycle error, got nil", run)
567			}
568			if run == 0 {
569				firstErr = err.Error()
570				continue
571			}
572			if err.Error() != firstErr {
573				t.Errorf("expected identical error chain on retry\nwant: %s\ngot:  %s", firstErr, err.Error())
574			}
575		}
576		if !strings.Contains(firstErr, "cycle") ||
577			!strings.Contains(firstErr, "a.conf") ||
578			!strings.Contains(firstErr, "link.conf") {
579			t.Errorf("expected a cycle chain naming a.conf and the link, got: %s", firstErr)
580		}
581	}
582	
583	// On a case-sensitive volume, two files whose names differ only in case are
584	// genuinely different files and must both expand; case folding must never be
585	// forced by the implementation.
586	func TestImportCaseDistinctOnCaseSensitiveFS(t *testing.T) {
587		dir := t.TempDir()
588		if fsCaseInsensitive(t, dir) {
589			t.Skip("requires a case-sensitive filesystem")
590		}
591		writeImportFile(t, filepath.Join(dir, "CASE.conf"), site("host-upper"))
592		writeImportFile(t, filepath.Join(dir, "case.conf"), site("host-lower"))
593	
594		blocks, err := parseInDir(t, dir, "import "+filepath.Join(dir, "*.conf")+"\n")
595		if err != nil {
596			t.Fatalf("expected no error, got: %v", err)
597		}
598		got := blockKeys(blocks)
599		if len(got) != 2 {
600			t.Fatalf("expected both case-distinct files to expand, got %v", got)
601		}
602		upper := strings.Join(got, ",")
603		if upper != "host-upper,host-lower" && upper != "host-lower,host-upper" {
604			t.Errorf("expected both hosts in a stable order, got %v", got)
605		}
606	}
607	
608	// A failed adaptation leaves no state that changes later adaptations:
609	// failing, then succeeding, then failing again through the same Adapter
610	// yields the same error category and chain both times.
611	func TestAdapterFailureIsStateless(t *testing.T) {
612		dir := t.TempDir()
613		root := filepath.Join(dir, "Caddyfile")
614		writeImportFile(t, filepath.Join(dir, "a.conf"), site("host-a"))
615		writeImportFile(t, filepath.Join(dir, "cyc.conf"), "import cyc-link.conf\n")
616		symlinkOrSkip(t, filepath.Join(dir, "cyc.conf"), filepath.Join(dir, "cyc-link.conf"))
617	
618		var captured []ServerBlock
619		adapter := Adapter{ServerType: captureServerType{blocks: &captured}}
620		failBody := []byte("import " + filepath.Join(dir, "cyc.conf") + "\n")
621		goodBody := []byte("import " + filepath.Join(dir, "a.conf") + "\n")
622	
623		out, _, err := adapter.Adapt(failBody, map[string]any{"filename": root})
624		if err == nil {
625			t.Fatal("expected the first adaptation to fail, got nil")
626		}
627		if out != nil {
628			t.Errorf("expected no partial output on failure, got %d bytes", len(out))
629		}
630		if captured != nil {
631			t.Error("expected Setup not to run on a failed adaptation")
632		}
633		firstErr := err.Error()
634	
635		if out, _, err := adapter.Adapt(goodBody, map[string]any{"filename": root}); err != nil {
636			t.Fatalf("expected a later adaptation to succeed, got: %v", err)
637		} else if len(out) == 0 {
638			t.Error("expected non-empty output from the successful adaptation")
639		}
640		if got := blockKeys(captured); len(got) != 1 || got[0] != "host-a" {
641			t.Errorf("expected [host-a] after recovery, got %v", got)
642		}
643	
644		captured = nil
645		out, _, err = adapter.Adapt(failBody, map[string]any{"filename": root})
646		if err == nil {
647			t.Fatal("expected the repeated failure to fail again, got nil")
648		}
649		if out != nil {
650			t.Errorf("expected no partial output on the repeated failure, got %d bytes", len(out))
651		}
652		if captured != nil {
653			t.Error("expected Setup not to run on the repeated failure")
654		}
655		if err.Error() != firstErr {
656			t.Errorf("expected the identical error chain after success\nwant: %s\ngot:  %s", firstErr, err.Error())
657		}
658	}
