88	func requireSuccess(t *testing.T, label string, got, want adaptOutcome, foreignDir, foreignMarker string) {
89		t.Helper()
90		if got.err != nil {
91			t.Fatalf("%s: expected success, got error: %v", label, got.err)
92		}
93		if want.err != nil {
94			t.Fatalf("%s: reference adaptation unexpectedly failed: %v", label, want.err)
95		}
96		if !bytes.Equal(got.out, want.out) {
97			t.Errorf("%s: body drift\nwant: %s\ngot:  %s", label, want.out, got.out)
98		}
99		if !reflect.DeepEqual(got.warnings, want.warnings) {
100			t.Errorf("%s: warnings drift\nwant: %v\ngot:  %v", label, want.warnings, got.warnings)
101		}
102		if bytes.Contains(got.out, []byte(foreignDir)) {
103			t.Errorf("%s: body leaks the other tree's path %q", label, foreignDir)
104		}
105		if foreignMarker != "" && bytes.Contains(got.out, []byte(foreignMarker)) {
106			t.Errorf("%s: body leaks the other tree's marker %q", label, foreignMarker)
107		}
108		for _, w := range got.warnings {
109			if strings.Contains(w.File+w.Message, foreignDir) || strings.Contains(w.File+w.Message, foreignMarker) {
110				t.Errorf("%s: warning leaks the other tree: %+v", label, w)
111			}
112		}
113	}
