115	// requireFailure asserts the outcome is the expected failed adaptation: no
116	// partially expanded body, an identical error chain, and diagnostics that
117	// only mention the failing tree.
118	func requireFailure(t *testing.T, label string, got, want adaptOutcome, ownDir, foreignDir string, wantSnippets ...string) {
119		t.Helper()
120		if got.err == nil {
121			t.Fatalf("%s: expected failure, got body %s", label, got.out)
122		}
123		if got.out != nil {
124			t.Errorf("%s: failed call returned a partial body (%d bytes)", label, len(got.out))
125		}
126		if want.err == nil {
127			t.Fatalf("%s: reference adaptation unexpectedly succeeded", label)
128		}
129		if got.err.Error() != want.err.Error() {
130			t.Errorf("%s: error drift\nwant: %s\ngot:  %s", label, want.err, got.err)
131		}
132		if !reflect.DeepEqual(got.warnings, want.warnings) {
133			t.Errorf("%s: warnings on failure drift\nwant: %v\ngot:  %v", label, want.warnings, got.warnings)
134		}
135		msg := got.err.Error()
136		if !strings.Contains(msg, ownDir) {
