// The trees below share one site shape: a redir followed (lexically) by a
// respond. In the default directive order redir runs first; the ALPHA tree
// flips that with the "order" global option so respond runs first. The
// adapted JSON therefore differs between the trees and reveals any leakage
// of one call's directive order into the other. Each tree also exercises
// nested, globbed and relative imports, which contribute header directives
// and anchor the diagnostics to the tree's own files.
func writeOrderTree(t *testing.T, dir, host string) {
	t.Helper()
	write := func(rel, content string) {
		p := filepath.Join(dir, rel)
		if err := os.MkdirAll(filepath.Dir(p), 0o755); err != nil {
			t.Fatalf("mkdir %s: %v", p, err)
		}
		if err := os.WriteFile(p, []byte(content), 0o644); err != nil {
			t.Fatalf("write %s: %v", p, err)
		}
	}
	marker := strings.SplitN(host, "-", 2)[0] // "alpha" or "bravo"
	write(filepath.Join(marker, "sub", "deep.caddy"), "header X-Deep "+marker+"\n")
	write(filepath.Join(marker, "dir.caddy"), "import sub/../sub/deep.caddy\n")
	write(filepath.Join(marker, "parts", "p1.caddy"), "header X-Glob "+marker+"\n")
	write(filepath.Join(marker, "site.caddy"), strings.Join([]string{
		"import dir.caddy",
		"import parts/*.caddy",
		"redir /" + marker + "-old /" + marker + "-new",
		`respond "` + strings.ToUpper(marker) + `"`,
	}, "\n")+"\n")
}

func alphaBody() []byte {
	return []byte(`{
	order respond before redir
}
alpha-iso.example {
	import alpha/site.caddy
}
`)
}

func bravoBody() []byte {
	return []byte(`bravo-iso.example {
	import bravo/site.caddy
}
`)
}

type adaptResult struct {
	out      []byte
	warnings []warning
	err      error
}

type warning = struct {
	File      string `json:"file,omitempty"`
	Line      int    `json:"line,omitempty"`
	Directive string `json:"directive,omitempty"`
	Message   string `json:"message,omitempty"`
}

func runAdapt(t *testing.T, adapter caddyfile.Adapter, root string, body []byte) adaptResult {
	t.Helper()
	out, warnings, err := adapter.Adapt(body, map[string]any{"filename": root})
	cp := make([]warning, len(warnings))
	for i, w := range warnings {
		cp[i] = warning(w)
	}
	return adaptResult{out: out, warnings: cp, err: err}
}

// subrouteHandlers extracts the handler names inside the site's subroute,
// in pipeline order, so a test can assert redir/respond ordering.
func subrouteHandlers(t *testing.T, out []byte) []string {
	t.Helper()
	var doc struct {
		Apps struct {
			HTTP struct {
				Servers map[string]struct {
					Routes []struct {
						Handle []struct {
							Routes []struct {
								Handle []struct {
									Handler string `json:"handler"`
								} `json:"handle"`
							} `json:"routes"`
						} `json:"handle"`
					} `json:"routes"`
				} `json:"servers"`
			} `json:"http"`
		} `json:"apps"`
	}
	if err := json.Unmarshal(out, &doc); err != nil {
		t.Fatalf("unmarshaling adapted JSON: %v\n%s", err, out)
	}
	var handlers []string
	for _, srv := range doc.Apps.HTTP.Servers {
		for _, route := range srv.Routes {
			for _, h := range route.Handle {
				for _, sr := range h.Routes {
					for _, hh := range sr.Handle {
						handlers = append(handlers, hh.Handler)
					}
				}
			}
		}
	}
	return handlers
}

func expectHandlerOrder(t *testing.T, label string, out []byte, wantFirst, wantSecond string) {
	t.Helper()
	handlers := subrouteHandlers(t, out)
	// headers may appear too; only compare the redir/respond relative order
	var redirIdx, respondIdx = -1, -1
	for i, h := range handlers {
		switch h {
		case "static_response":
			// both redir and respond encode to static_response; distinguish
			// by re-decoding status code below instead
		}
	}
	_ = redirIdx
	_ = respondIdx
	// Decode more precisely: find static_response handlers in order and look
	// at the presence of a redirect status code (302) vs a plain body.
	var doc struct {
		Apps struct {
			HTTP struct {
				Servers map[string]struct {
					Routes []struct {
						Handle []struct {
							Routes []struct {
								Handle []struct {
									StatusCode int    `json:"status_code"`
									Body       string `json:"body"`
								} `json:"handle"`
							} `json:"routes"`
						} `json:"handle"`
					} `json:"routes"`
				} `json:"servers"`
			} `json:"http"`
		} `json:"apps"`
	}
	if err := json.Unmarshal(out, &doc); err != nil {
		t.Fatalf("unmarshaling adapted JSON: %v", err)
	}
	var order []string
	for _, srv := range doc.Apps.HTTP.Servers {
		for _, route := range srv.Routes {
			for _, h := range route.Handle {
				for _, sr := range h.Routes {
					for _, hh := range sr.Handle {
						if hh.StatusCode == 302 {
							order = append(order, "redir")
						} else if hh.Body != "" {
							order = append(order, "respond")
						}
					}
				}
			}
		}
	}
	firstRedir, firstRespond := indexOf(order, "redir"), indexOf(order, "respond")
	if firstRedir < 0 || firstRespond < 0 {
		t.Fatalf("%s: expected one redir and one respond, got %v (handlers %v)", label, order, handlers)
	}
	gotFirst, gotSecond := order[firstRedir], order[firstRespond]
	if firstRedir < firstRespond {
		gotFirst, gotSecond = "redir", "respond"
	}
	if gotFirst != wantFirst || gotSecond != wantSecond {
		t.Errorf("%s: expected %s before %s, got order %v", label, wantFirst, wantSecond, order)
	}
}

func indexOf(s []string, v string) int {
	for i, x := range s {
		if x == v {
			return i
		}
	}
	return -1
}

func assertResultEqual(t *testing.T, label string, got, want adaptResult) {
	t.Helper()
	if (got.err == nil) != (want.err == nil) {
		t.Fatalf("%s: error drift: want %v, got %v", label, want.err, got.err)
	}
	if want.err != nil {
		if got.err.Error() != want.err.Error() {
			t.Errorf("%s: error text drift\nwant: %s\ngot:  %s", label, want.err, got.err)
		}
	}
	if !bytes.Equal(got.out, want.out) {
		t.Errorf("%s: body drift\nwant: %s\ngot:  %s", label, want.out, got.out)
	}
	if !reflect.DeepEqual(got.warnings, want.warnings) {
		t.Errorf("%s: warnings drift\nwant: %v\ngot:  %v", label, want.warnings, got.warnings)
	}
}

