					t.Errorf("%s: partial body on failure (%d bytes)", label, len(r.out))
				}
				if r.err.Error() != wantFail.err.Error() {
					t.Errorf("%s: error text drift\nwant: %s\ngot:  %s", label, wantFail.err, r.err)
