32	// The trees below share one site shape: a redir followed (lexically) by a
33	// respond. In the default directive order redir runs first; the ALPHA tree
34	// flips that with the "order" global option so respond runs first. The
35	// adapted JSON therefore differs between the trees and reveals any leakage
36	// of one call's directive order into the other. Each tree also exercises
37	// nested, globbed and relative imports, which contribute header directives
38	// and anchor the diagnostics to the tree's own files.
39	func writeOrderTree(t *testing.T, dir, host string) {
40		t.Helper()
41		marker := strings.SplitN(host, "-", 2)[0] // "alpha" or "bravo"
42		write := func(rel, content string) {
43			writeAdaptFile(t, filepath.Join(dir, rel), content)
44		}
45		write(filepath.Join(marker, "sub", "deep.caddy"), "vars deep "+marker+"\n")
46		write(filepath.Join(marker, "dir.caddy"), "import sub/../sub/deep.caddy\n")
47		write(filepath.Join(marker, "parts", "p1.caddy"), "vars glob "+marker+"\n")
48		write(filepath.Join(marker, "site.caddy"), strings.Join([]string{
49			"import dir.caddy",
50			"import parts/*.caddy",
51			"redir /" + marker + "-old /" + marker + "-new",
52			`respond "` + strings.ToUpper(marker) + `"`,
53		}, "\n")+"\n")
54	}
55	
56	func alphaBody() []byte {
57		return []byte(`{
58		order respond before redir
59	}
60	alpha-iso.example {
61		import alpha/site.caddy
62	}
63	`)
64	}
65	
66	func bravoBody() []byte {
67		return []byte(`bravo-iso.example {
68		import bravo/site.caddy
69	}
70	`)
71	}
