131	func expectHandlerOrder(t *testing.T, label string, out []byte, wantFirst, wantSecond string) {
132		t.Helper()
133		order := redirRespondOrder(t, out)
134		redirAt, respondAt := indexOf(order, "redir"), indexOf(order, "respond")
135		if redirAt < 0 || respondAt < 0 {
136			t.Fatalf("%s: expected one redir and one respond, got %v", label, order)
137		}
138		gotFirst, gotSecond := "redir", "respond"
139		if respondAt < redirAt {
140			gotFirst, gotSecond = "respond", "redir"
141		}
142		if gotFirst != wantFirst || gotSecond != wantSecond {
143			t.Errorf("%s: expected %s before %s, got pipeline %v", label, wantFirst, wantSecond, order)
144		}
145	}
146	
147	func indexOf(s []string, v string) int {
148		for i, x := range s {
149			if x == v {
150				return i
151			}
152		}
153		return -1
154	}
