cat > caddyconfig/httpcaddyfile/scratch_multiorder_test.go <<'EOF'
package httpcaddyfile

import (
	"testing"

	"github.com/caddyserver/caddy/v2/caddyconfig/caddyfile"
)

func TestScratchMultiOrder(t *testing.T) {
	body := []byte(`{
	order respond first
	order redir last
}
multi-iso.example {
	vars x 1
	redir /a /b
	respond "M"
}
`)
	a := caddyfile.Adapter{ServerType: ServerType{}}
	o1, _, err := a.Adapt(body, nil)
	if err != nil {
		t.Fatal(err)
	}
	// twice more; outputs must remain identical (no global accumulation)
	for i := 0; i < 2; i++ {
		oi, _, err := a.Adapt(body, nil)
		if err != nil {
			t.Fatal(err)
		}
		if string(oi) != string(o1) {
			t.Fatalf("run %d drifted", i)
		}
	}
	order := redirRespondOrder(t, o1)
	if order[0] != "respond" || order[len(order)-1] != "redir" {
		t.Fatalf("expected respond first / redir last, got %v", order)
	}
	// a separate default-order adaptation right after must be unaffected
	b := []byte("def-iso.example {\nredir /a /b\nrespond \"D\"\n}\n")
	ob, _, err := a.Adapt(b, nil)
	if err != nil {
		t.Fatal(err)
	}
	do := redirRespondOrder(t, ob)
	if do[0] != "redir" {
		t.Fatalf("default order leaked, got %v", do)
	}
}
EOF
go test ./caddyconfig/httpcaddyfile/ -run TestScratchMultiOrder -race -v 2>&1 | tail -8
rm caddyconfig/httpcaddyfile/scratch_multiorder_test.go

